const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const puertoRico = ee.FeatureCollection('FAO/GAUL_SIMPLIFIED_500M/2015/v5')
    .filter(ee.Filter.eq('ADM0_NAME', 'Puerto Rico'))
    .first()
    .geometry();

  const date1_start = '2016-09-21';
  const date1_end = '2016-09-22'; // Exclusive end for filterDate, so covers Sept 21
  const date2_start = '2016-09-22';
  const date2_end = '2016-09-23'; // Exclusive end for filterDate, so covers Sept 22

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG');

  const col1 = collection.filterDate(date1_start, date1_end).filterBounds(puertoRico);
  const col2 = collection.filterDate(date2_start, date2_end).filterBounds(puertoRico);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`2016-09-21 Images: ${size1}`);
    console.log(`2016-09-22 Images: ${size2}`);
    console.log("Empty Collection (No images found for one or both dates).");
    console.log("C1");
    return;
  }

  // 3. Processing (Cloud masking and selecting the average radiance band)
  // Mask function for VIIRS DNB: Keep only good quality pixels (q_flag = 0)
  // This helps remove clouds, stray light, etc.
  const maskClouds = function(image) {
    const qFlag = image.select('q_flag');
    // q_flag == 0 means "good quality"
    return image.updateMask(qFlag.eq(0)).select('avg_rad');
  };

  const img1 = col1.map(maskClouds).mean().clip(puertoRico);
  const img2 = col2.map(maskClouds).mean().clip(puertoRico);

  const scale = 1000; // Using a sufficiently large scale to prevent timeout, while representing the area.

  // Calculate valid pixel count for img1
  const count1 = await img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: puertoRico,
    scale: scale,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  // Calculate valid pixel count for img2
  const count2 = await img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: puertoRico,
    scale: scale,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`2016-09-21 Valid Pixels: ${count1}`);
    console.log(`2016-09-22 Valid Pixels: ${count2}`);
    console.log("No Valid Pixels (after cloud masking/processing, 0 pixels remain for one or both dates).");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const meanRad1 = await img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: puertoRico,
    scale: scale,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const meanRad2 = await img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: puertoRico,
    scale: scale,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  // 5. Validation & Final Answer
  if (meanRad1 === null || meanRad2 === null || isNaN(meanRad1) || isNaN(meanRad2)) {
    console.log(`2016-09-21 Mean Radiance: ${meanRad1}`);
    console.log(`2016-09-22 Mean Radiance: ${meanRad2}`);
    console.log("Calculation Failure (Result is None, NaN, or invalid).");
    console.log("C3");
    return;
  }

  console.log(`2016-09-21 Images: ${size1}, Valid Pixels: ${count1}, Mean Radiance: ${meanRad1.toFixed(4)}`);
  console.log(`2016-09-22 Images: ${size2}, Valid Pixels: ${count2}, Mean Radiance: ${meanRad2.toFixed(4)}`);

  if (meanRad2 < meanRad1) {
    console.log("A"); // Yes, intensity declined
  } else {
    console.log("B"); // No, intensity did not decline
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
